<script setup lang="ts">
import { stopCoverage } from 'node:v8'
import { nextTick } from 'vue'

definePageMeta({
  layout: 'default',
  middleware: async (to) => {
    const { slug } = to.params

    // Проверяем, число ли это
    const isNumeric = !isNaN(Number(slug)) && String(slug).trim() !== ''

    if (isNumeric) {
      // Прямой запрос к API (выполнится на сервере)
      try {
        const data: any = await $fetch(`/api/sanity/partners`, {
          query: { id: slug }
        })

        if (data?.slug) {
          // Чистый редирект до рендера
          return navigateTo(`/promo/${data.slug}`, { replace: true })
        }
      } catch (e) {
        console.error('Redirect middleware error', e)
      }
    }
  }
})

const cms = ref('sanity')

const route = useRoute()

const slugRoute = route.params.slug

// Create Link
function encodeData(data: { id: number, app: string }) {
  return btoa(JSON.stringify(data))
}

const idOrSlug = computed(() => route.params.slug)

const isNumericId = computed(() => {
  const val = String(idOrSlug.value)
  return !isNaN(Number(val)) && val.trim() !== ''
})

const urlData = computed<{ id: number, app: string } | null>(() => {
  try {
    return route.query.data
      ? JSON.parse(atob(String(route.query.data)))
      : null
  } catch {
    return null
  }
})
const id = computed(() => route.params.id)
const app = computed(() => urlData.value?.app ?? null)

const email = ref('')

const emailC = computed({
  get: () => email.value,
  set: (v) => {
    email.value = v.toLowerCase()
  }
})

const name = ref('')

const nameC = computed({
  get: () => name.value,
  set: (v) => {
    name.value = v
  }
})

const selectedAge = ref<string | null>(null)

const loading = ref<boolean>(false)
const success = ref<boolean>(false)

const { data, pending, error } = useLazyFetch<any>(`/api/${cms.value}/partners`, {
  key: computed(() => `partner-${idOrSlug.value}`).value,
  // Выполняем всегда, подставляя дефолт 102, если параметра нет
  immediate: true,
  query: computed(() => {
    const identifier = idOrSlug.value || '102'
    return isNumericId.value
      ? { id: identifier }
      : { slug: identifier }
  }),
  server: true
})

const err = ref(false)
const errorReason = ref<null | number>(null) // 1 - error data, 2 - network error

const submit = async () => {
  err.value = false
  errorReason.value = null
  success.value = false

  if (!email.value) {
    err.value = true
    errorReason.value = 1
    return
  }

  loading.value = true

  const partnerName = data?.value.name || 'Partner'

  try {
    await $fetch(`/api/${cms.value}/users`, {
      method: 'POST',
      body: {
        email: email.value,
        childrenName: name.value,
        partner: id.value || route.params.id || route.params.slug || null,
        partnerName,
        childrenAge: selectedAge.value
      }
    })

    success.value = true
    step.value = 2

    await nextTick()
    window.scrollTo({
      top: 0,
      behavior: 'smooth' // Можно заменить на 'auto' для мгновенного прыжка без анимации
    })
    // email.value = ''
    // password.value = ''
  } catch (e: any) {
    err.value = true
    errorReason.value = 2
  } finally {
    loading.value = false
  }
}
const router = useRouter()

function isValidEmail(email: string) {
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/
  return emailRegex.test(email)
}

const parsedAgeLabels = computed(() => {
  const raw = data.value?.landing_v2_step_1_block_2_loc_age_range ?? '1-2,3-4,5-6,7+'

  let parsed: string[] | null

  try {
    parsed = raw.split(',')
  } catch (error: any) {
    parsed = null
  }

  return parsed
})

const step = computed({
  get() {
    const s = Number(route.query.step)
    return isNaN(s) ? 1 : s
  },
  set(newStep) {
    // push добавляет шаг в историю браузера
    router.push({
      query: {
        ...route.query,
        step: newStep || undefined // если 0, убираем из URL для чистоты
      }
    })
  }
})

function openAppStore() {
  window.open('https://apps.apple.com/app/id6447677737', '_blank', 'noopener,noreferrer')
}

function prevStep() {
  step.value = step.value - 1
}

const passwordHidden = ref(true)
const btnRef = ref<HTMLButtonElement | null>(null)
const textRef = ref<HTMLSpanElement | null>(null)
const fontSize = ref<number | null>(null)

const windowWidth = ref(0)
const isDesktop = computed(() => windowWidth.value >= 1136)

function updateWidth() {
  windowWidth.value = window.innerWidth
}

// watchEffect(() => {
//   if (parsedAgeLabels.value?.[0]) {
//     selectedAge.value = parsedAgeLabels.value[0];
//   }
// })

const pageTitle = computed(() => {
  return data.value?.landing_v2_website_loc_title ? `${data.value.landing_v2_website_loc_title} — AmayaKids` : 'AmayaKids'
})

const pageDescription = computed(() => {
  // Замените на ваше описание из data или дефолтное
  return data.value?.landing_v2_website_loc_description || 'Развивающие игры для детей от AmayaKids.'
})

const pageImage = computed(() => {
  // Ссылка на картинку для превью в соцсетях
  return data.value?.logoUrl
})

useSeoMeta({
  title: pageTitle,
  description: pageDescription,

  // Open Graph (Facebook, Telegram, WhatsApp, VK)
  ogTitle: pageTitle,
  ogDescription: pageDescription,
  ogImage: pageImage,
  ogType: 'website',

  // Twitter / X
  twitterCard: 'summary_large_image',
  twitterTitle: pageTitle,
  twitterDescription: pageDescription,
  twitterImage: pageImage
})

useHead({
  title: computed(() => {
    return data.value?.landing_v2_website_loc_title
      ? `${data.value.landing_v2_website_loc_title} — AmayaKids`
      : (slugRoute ? `${(String(slugRoute)).toUpperCase()} — AmayaKids` : 'AmayaKids')
  }),
  meta: [
    {
      name: 'theme-color',
      content: computed(() => {
        return isDesktop.value ? '#f3f3f3' : '#ffffff'
      })
    }
  ],
  bodyAttrs: {
    class: 'promo-page-body'
  },
  htmlAttrs: {
    class: 'promo-page-html'
  }
})

const videoRef = ref(null)

function onInputEmail() {
  if (isValidEmail(email.value)) {
    err.value = false
  }
}

onMounted(() => {
  updateWidth()
  window.addEventListener('resize', updateWidth)
})

onBeforeUnmount(() => {
  window.removeEventListener('resize', updateWidth)
})
</script>

